  <script>
    (function () {
      var banner = document.getElementById('cookieBanner');
      var modal = document.getElementById('prefsModal');
      var manageBtn = document.getElementById('managePrefsBtn');
      var acceptBtn = document.getElementById('acceptCookiesBtn');
      var closeBtn = document.getElementById('closeModalBtn');
      var saveBtn = document.getElementById('savePrefsBtn');
      var acceptAllModal = document.getElementById('acceptAllModalBtn');

      function hideBanner() {
        banner.classList.add('hidden');
      }

      function openModal() {
        modal.classList.add('active');
        closeBtn.focus();
        document.body.style.overflow = 'hidden';
      }

      function closeModal() {
        modal.classList.remove('active');
        document.body.style.overflow = '';
        manageBtn.focus();
      }

      acceptBtn.addEventListener('click', function () {
        hideBanner();
      });

      manageBtn.addEventListener('click', function () {
        openModal();
      });

      closeBtn.addEventListener('click', function () {
        closeModal();
      });

      saveBtn.addEventListener('click', function () {
        closeModal();
        hideBanner();
